{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "is_hardware_anomaly_window",
  "per_column": [
    {
      "name": "is_hardware",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether the incident is hardware is a necessary precondition component of the focus but not deterministic of it (being hardware does not imply anomaly window). It carries genuine predictive signal about whether a record can be in the hardware anomaly window without fully restating the target."
    },
    {
      "name": "priority_score",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Priority is a legitimate external attribute known at incident time that plausibly correlates with anomalous hardware bursts (e.g., higher-priority spikes). It is not a component or function of the focus."
    },
    {
      "name": "resolution_hours",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Resolution time is only knowable after the incident is closed (post-outcome), so using it to predict whether the record is in the anomaly window constitutes temporal leakage relative to prediction time."
    },
    {
      "name": "hw_incidents_last_7d",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "A rolling count of recent hardware incidents is exactly the kind of contextual, pre-outcome signal that indicates an anomalous surge. It lies outside the focus and plausibly carries strong predictive signal for anomaly windows."
    },
    {
      "name": "hw_anomaly_window",
      "role": "restatement",
      "is_predictor": false,
      "rationale": "This is essentially the focus variable itself (hardware anomaly window flag) restated. Its value distribution mirrors the target; using it is trivial leakage/restatement, not a predictor."
    },
    {
      "name": "hw_resolution_zscore",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "A z-score of resolution time is derived from resolution_hours, a post-outcome quantity, and is often used to define anomalies. It leaks the outcome and is not available at prediction time."
    }
  ],
  "n_predictors": 3,
  "predictive_utility": 0.45,
  "rationale": "Three columns (is_hardware, priority_score, hw_incidents_last_7d) are legitimate pre-outcome predictors, with hw_incidents_last_7d providing the strongest genuine leverage for detecting anomalous hardware surges. However, half the added set is compromised: hw_anomaly_window is a near-restatement of the focus, while resolution_hours and hw_resolution_zscore are post-outcome quantities that leak. As a set, the predictive value beyond the original columns is moderate, dragged down by leakage and restatement."
}

